const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const j = items[i].json || {};
  const msg = j.message || {};
  const caption = (msg.caption || msg.text || '').toString();
  const chatId = (msg.chat && msg.chat.id) ? msg.chat.id : '';
  let invoiceType = 'خرید';
  if (caption.indexOf('فروش') !== -1) { invoiceType = 'فروش'; }
  else if (caption.indexOf('خرید') !== -1) { invoiceType = 'خرید'; }
  const binary = items[i].binary || {};
  const key = Object.keys(binary)[0];
  if (!key) { throw new Error('تصویری در پیام یافت نشد. لطفاً عکس فاکتور را ارسال کنید.'); }
  const buffer = await this.helpers.getBinaryDataBuffer(i, key);
  const base64 = buffer.toString('base64');
  const mime = binary[key].mimeType || 'image/jpeg';
  const dataUrl = 'data:' + mime + ';base64,' + base64;
  const systemPrompt = 'You are a precise accounting OCR assistant for Iranian invoices. Read the invoice image and extract structured data. Return ONLY one valid JSON object with no markdown and no explanation. Use exactly these keys: invoice_number, invoice_date, party_name, description, quantity, amount_before_tax, tax_rate, vat_amount, total_with_tax. Output every number and every digit using Western Arabic numerals (0-9) only, never Persian or Arabic-Indic digits. Numbers must be plain digits with no thousands separators and no currency words. Read each digit carefully and double-check the amounts so totals are consistent. Keep invoice_date exactly as printed but with Western digits (Jalali calendar is fine). Use empty string for missing text fields and 0 for missing numbers.';
  const userText = 'این تصویر یک فاکتور ' + invoiceType + ' است. اطلاعات آن را دقیق استخراج کن و فقط یک شیء JSON با ارقام لاتین برگردان.';
  const aiBody = {
    model: 'qwen/qwen3.6-27b',
    temperature: 0,
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: [
        { type: 'text', text: userText },
        { type: 'image_url', image_url: { url: dataUrl } }
      ] }
    ]
  };
  out.push({ json: { invoiceType: invoiceType, chatId: chatId, caption: caption, aiBody: aiBody } });
}
return out;

const resp = $json || {};
let content = '';
try { content = resp.choices[0].message.content; } catch (e) { content = ''; }
if (!content) { throw new Error('پاسخ هوش مصنوعی خالی یا نامعتبر بود.'); }
const faDigits = '۰۱۲۳۴۵۶۷۸۹';
const arDigits = '٠١٢٣٤٥٦٧٨٩';
const normDigits = (val) => {
  let str = String(val === null || val === undefined ? '' : val);
  for (let d = 0; d < 10; d++) {
    str = str.split(faDigits[d]).join(String(d));
    str = str.split(arDigits[d]).join(String(d));
  }
  return str;
};
let clean = normDigits(content).trim();
clean = clean.split(String.fromCharCode(96)).join('');
if (clean.slice(0, 4).toLowerCase() === 'json') { clean = clean.slice(4); }
clean = clean.trim();
const a = clean.indexOf('{');
const b = clean.lastIndexOf('}');
if (a !== -1 && b !== -1) { clean = clean.slice(a, b + 1); }
let data;
try { data = JSON.parse(clean); } catch (err) { throw new Error('استخراج JSON از پاسخ هوش مصنوعی ناموفق بود: ' + clean.slice(0, 300)); }
const prep = $('آماده‌سازی درخواست هوش مصنوعی').item.json;
const toNum = (v) => {
  if (v === null || v === undefined || v === '') return 0;
  let str = normDigits(v).replace(/[,٬،\s]/g, '').replace(/[^0-9.\-]/g, '');
  if (str === '' || str === '-' || str === '.') return 0;
  const n = Number(str);
  return isNaN(n) ? 0 : n;
};
const cleanText = (v) => normDigits(v).trim();
const amountBeforeTax = toNum(data.amount_before_tax);
let vatAmount = toNum(data.vat_amount);
let totalWithTax = toNum(data.total_with_tax);
if (!vatAmount && totalWithTax && amountBeforeTax) { vatAmount = totalWithTax - amountBeforeTax; }
if (!totalWithTax) { totalWithTax = amountBeforeTax + vatAmount; }
const row = {
  'نوع فاکتور': prep.invoiceType,
  'تاریخ فاکتور': cleanText(data.invoice_date),
  'شماره فاکتور': cleanText(data.invoice_number),
  'طرف حساب': cleanText(data.party_name),
  'شرح کالا/خدمات': cleanText(data.description),
  'تعداد': toNum(data.quantity),
  'مبلغ بدون مالیات': amountBeforeTax,
  'نرخ مالیات (درصد)': toNum(data.tax_rate),
  'مالیات ارزش افزوده': vatAmount,
  'مبلغ کل با مالیات': totalWithTax,
  'زمان ثبت': $now.toISO(),
  'شناسه چت': prep.chatId
};
return { json: row };

